// Database for TransMilenio Bogotá System (Stations, Routes, Schedules, Stops, News)

export interface Station {
  id: string
  name: string
  zone: "A" | "B" | "C" | "D" | "E" | "F" | "G" | "H" | "J" | "K" | "L" | "M"
  address: string
  lat: number
  lng: number
  isPortal: boolean
  accessible: boolean
  crowdLevel: "low" | "medium" | "high"
  routes: string[]
}

export interface RouteStop {
  stationId: string
  stationName: string
  minutesFromStart: number
}

export interface Route {
  code: string
  name: string
  type: "troncal" | "dual" | "zonal" | "alimentadora"
  zone: string
  color: string
  textColor: string
  origin: string
  destination: string
  frequencyPeak: string
  frequencyOffPeak: string
  hoursWeekday: string
  hoursSaturday: string
  hoursSunday: string
  stops: RouteStop[]
}

export interface SystemNewsAlert {
  id: string
  tag: string
  tagColor: string
  time: string
  title: string
  body: string
  affectedRoutes?: string[]
  affectedStations?: string[]
  action?: string
}

