// -------------------------------------------------------------
// HELPER FUNCTIONS & DATA SEARCH
// -------------------------------------------------------------
export function getStationById(id: string): Station | undefined {
  return STATIONS_DATABASE.find((s) => s.id === id)
}

export function getRouteByCode(code: string): Route | undefined {
  if (!code) return undefined
  const cleanCode = code.toUpperCase().trim().split("-")[0]

  // 1. Check existing explicit match
  const exact = ROUTES_DATABASE.find((r) => r.code.toUpperCase() === cleanCode)
  if (exact) return exact

  // 2. Check if cleanCode matches dual-letter prefix (e.g. searching "K309" matches "KB309")
  const dualMatch = ROUTES_DATABASE.find((r) => {
    const rc = r.code.toUpperCase()
    return rc.includes(cleanCode) || cleanCode.includes(rc)
  })
  if (dualMatch) return dualMatch

  // 3. Check if number part matches (e.g. searching "309" matches "K309", "B309", "KB309")
  const numPart = cleanCode.replace(/^[A-Z]+/, "")
  if (numPart.length >= 2) {
    const numMatch = ROUTES_DATABASE.find((r) => r.code.toUpperCase().includes(numPart))
    if (numMatch) return numMatch
  }

  // 4. Dynamic Generator for ANY route code (e.g. K309, B309, H72, J24, A61, F60)
  const letter = cleanCode.charAt(0)
  const zoneInfo = (ZONE_METADATA as any)[letter] || { destName: "Estación de Destino", zoneName: "SITP / Troncal", color: "#c67139" }

  const generatedRoute: Route = {
    code: cleanCode,
    name: `Ruta Expresa ${cleanCode} ➔ ${zoneInfo.destName}`,
    type: cleanCode.length > 3 ? "zonal" : "troncal",
    zone: zoneInfo.zoneName,
    color: zoneInfo.color,
    textColor: "#ffffff",
    origin: "Portal del Sistema",
    destination: zoneInfo.destName,
    frequencyPeak: "4 - 8 min",
    frequencyOffPeak: "8 - 12 min",
    hoursWeekday: "04:30 - 23:00",
    hoursSaturday: "05:00 - 23:00",
    hoursSunday: "06:00 - 22:00",
    stops: [
      { stationId: "suba", stationName: "Paradero Origen", minutesFromStart: 0 },
      { stationId: "cll100", stationName: "Calle 100", minutesFromStart: 18 },
      { stationId: "marly", stationName: "Estación Marly", minutesFromStart: 28 },
      { stationId: "cll26", stationName: "Estación Calle 26", minutesFromStart: 35 },
      { stationId: "dest", stationName: zoneInfo.destName, minutesFromStart: 50 },
    ],
  }

  ROUTES_DATABASE.push(generatedRoute)
  return generatedRoute
}

export interface LiveArrival {
  line: string
  dest: string
  type: string
  mins: number
  bg: string
  color: string
}

export function getStationArrivals(stationId: string): LiveArrival[] {
  const station = getStationById(stationId)
  if (!station) return []

  const result: LiveArrival[] = []

  // Match routes passing through this station
  ROUTES_DATABASE.forEach((route, idx) => {
    const hasStop = route.stops.some((st) => st.stationId === stationId)
    if (hasStop || station.routes.includes(route.code)) {
      // Deterministic pseudo-random minutes based on station + route index
      const mins = Math.max(1, ((stationId.length * 3 + idx * 4 + 2) % 14) + 1)
      let typeLabel = "Troncal Expreso"
      if (route.type === "alimentadora") typeLabel = "Alimentador Zonal"
      else if (route.type === "dual") typeLabel = "Ruta Dual"
      else if (route.type === "zonal") typeLabel = "SITP Zonal"
      else if (route.code.startsWith("B1")) typeLabel = "Ruta Fácil"

      result.push({
        line: route.code,
        dest: route.destination,
        type: typeLabel,
        mins,
        bg: route.color || "var(--accent)",
        color: route.textColor || "#ffffff",
      })
    }
  })

  // Sort by shortest waiting time
  return result.sort((a, b) => a.mins - b.mins)
}

export function searchTransMilenio(query: string) {
  const q = query.toLowerCase().trim()
  if (!q) return { stations: [], routes: [] }

  // Check if query looks like a route code
  if (q.length <= 6) {
    const dynamicRoute = getRouteByCode(q)
    if (dynamicRoute && !ROUTES_DATABASE.some((r) => r.code.toLowerCase() === q)) {
      ROUTES_DATABASE.push(dynamicRoute)
    }
  }

  const matchedStations = STATIONS_DATABASE.filter(
    (s) => s.name.toLowerCase().includes(q) || s.address.toLowerCase().includes(q) || s.zone.toLowerCase() === q
  )

  const matchedRoutes = ROUTES_DATABASE.filter(
    (r) =>
      r.code.toLowerCase().includes(q) ||
      r.name.toLowerCase().includes(q) ||
      r.origin.toLowerCase().includes(q) ||
      r.destination.toLowerCase().includes(q)
  )

  return { stations: matchedStations, routes: matchedRoutes }
}

